/*
 * Write src/data/release.ts from the newest published release.
 *
 * Every file name, byte count and digest on the download section comes from
 * here, so none of them is typed by hand and none of them can drift from what
 * the release actually carries. The digests are read out of the release's own
 * SHA256SUMS.txt, which the publish job generated from the per-platform
 * manifests the build wrote.
 *
 *     node scripts/release-data.mjs
 *
 * Needs network access. The generated file is committed; run this when a new
 * release is published, and commit what it writes.
 */

import { writeFile } from 'node:fs/promises';

const REPOSITORY = process.env.FC_REPOSITORY ?? 'fontcarver/fontcarver';
const API = `https://api.github.com/repos/${REPOSITORY}/releases`;

/** Which platform each installer belongs to, and how to describe it. */
const PLATFORMS = [
  { id: 'linux', match: [/\.deb$/, /\.rpm$/, /\.AppImage$/] },
  { id: 'macos', match: [/\.dmg$/] },
  { id: 'windows', match: [/-setup\.exe$/, /-portable\.zip$/] },
];

const KIND = [
  [/\.deb$/, 'deb'],
  [/\.rpm$/, 'rpm'],
  [/\.AppImage$/, 'appimage'],
  [/\.dmg$/, 'dmg'],
  [/-setup\.exe$/, 'nsis'],
  [/-portable\.zip$/, 'portable'],
];

async function json(url) {
  const response = await fetch(url, {
    headers: { accept: 'application/vnd.github+json', 'user-agent': 'fontcarver-site' },
  });
  if (!response.ok) throw new Error(`${url} answered ${response.status}`);
  return response.json();
}

const releases = await json(API);
const release = releases.find((entry) => !entry.draft);
if (!release) throw new Error('no published release');

const sums = release.assets.find((asset) => asset.name === 'SHA256SUMS.txt');
if (!sums) throw new Error('the release carries no SHA256SUMS.txt');
const digests = new Map(
  (await (await fetch(sums.browser_download_url)).text())
    .split('\n')
    .filter(Boolean)
    .map((line) => {
      const [digest, name] = line.split('  ');
      return [name, digest];
    }),
);

const files = [];
for (const { id, match } of PLATFORMS) {
  for (const pattern of match) {
    const asset = release.assets.find((entry) => pattern.test(entry.name));
    if (!asset) continue;
    const kind = KIND.find(([test]) => test.test(asset.name))?.[1];
    files.push({
      platform: id,
      kind,
      name: asset.name,
      bytes: asset.size,
      sha256: digests.get(asset.name) ?? '',
      url: asset.browser_download_url,
    });
  }
}

const missing = files.filter((file) => !file.sha256);
if (missing.length) throw new Error(`no digest for ${missing.map((f) => f.name).join(', ')}`);

const data = {
  tag: release.tag_name,
  version: release.tag_name.replace(/^v/, ''),
  prerelease: release.prerelease,
  published: release.published_at.slice(0, 10),
  page: release.html_url,
  checksums: sums.browser_download_url,
  files,
};

const header = `/* Generated by site/scripts/release-data.mjs. Do not edit.
 *
 * The published release, read from the GitHub API: every byte count below is
 * the asset's own size and every digest comes from the release's
 * SHA256SUMS.txt, which was generated from the per-platform manifests the
 * build wrote. Re-run the script after publishing a release.
 */

export interface ReleaseFile {
  platform: 'linux' | 'macos' | 'windows';
  kind: 'deb' | 'rpm' | 'appimage' | 'dmg' | 'nsis' | 'portable';
  name: string;
  bytes: number;
  sha256: string;
  url: string;
}

export interface Release {
  tag: string;
  version: string;
  prerelease: boolean;
  published: string;
  page: string;
  checksums: string;
  files: ReleaseFile[];
}

export const release: Release = `;

await writeFile(
  new URL('../src/data/release.ts', import.meta.url),
  `${header}${JSON.stringify(data, null, 2)};\n`,
  'utf8',
);
console.log(`wrote src/data/release.ts for ${data.tag}: ${files.length} files`);
